const ZKR_IMGS = {
  logo: "data:image/png;base64,",
  feature: "data:image/png;base64,",
  screen1: "data:image/jpeg;base64,",
  screen2: "data:image/jpeg;base64,",
  screen3: "data:image/jpeg;base64,",
  screen4: "data:image/jpeg;base64,",
};
document.querySelectorAll("[data-zkr-img]").forEach(el=>{const k=el.dataset.zkrImg;if(ZKR_IMGS[k])el.src=ZKR_IMGS[k];});
